-- NEURA SOCIAL v3 / Supabase starter schema
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique not null, display_name text, bio text default '', avatar_url text, created_at timestamptz default now());
create table if not exists public.posts (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, body text default '', media_url text, media_type text check (media_type in ('image','video','audio')), created_at timestamptz default now());
create table if not exists public.likes (post_id uuid references public.posts(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, created_at timestamptz default now(), primary key(post_id,user_id));
create table if not exists public.comments (id uuid primary key default gen_random_uuid(), post_id uuid references public.posts(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, body text not null, created_at timestamptz default now());
create table if not exists public.follows (follower_id uuid references auth.users(id) on delete cascade, following_id uuid references auth.users(id) on delete cascade, created_at timestamptz default now(), primary key(follower_id,following_id), check (follower_id <> following_id));
alter table public.profiles enable row level security; alter table public.posts enable row level security; alter table public.likes enable row level security; alter table public.comments enable row level security; alter table public.follows enable row level security;
create policy "profiles readable" on public.profiles for select using (true); create policy "users insert own profile" on public.profiles for insert with check (auth.uid()=id); create policy "users update own profile" on public.profiles for update using (auth.uid()=id);
create policy "posts readable" on public.posts for select using (true); create policy "users create posts" on public.posts for insert with check (auth.uid()=user_id); create policy "users delete own posts" on public.posts for delete using (auth.uid()=user_id);
create policy "likes readable" on public.likes for select using (true); create policy "users manage own likes" on public.likes for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "comments readable" on public.comments for select using (true); create policy "users comment" on public.comments for insert with check (auth.uid()=user_id); create policy "users delete own comments" on public.comments for delete using (auth.uid()=user_id);
create policy "follows readable" on public.follows for select using (true); create policy "users manage own follows" on public.follows for all using (auth.uid()=follower_id) with check (auth.uid()=follower_id);
-- Create a Storage bucket named neura-media in Supabase Storage. Keep it private by default and use authenticated upload policies.
